<?php
/** Read-only document workspace and contextual settings help. @package Booster_For_WooCommerce/admin */
defined('ABSPATH') || exit;
final class WCJ_Document_Workspace {
 public static function groups(){return require __DIR__.'/document-workspace-groups.php';}
 public static function edition(){return WCJ_Document_Label_Job::edition();}
 public static function allowed($id){$core=WCJ_Job_Store::core();return current_user_can('manage_woocommerce')&&$core&&isset($core->all_modules[$id])&&(!function_exists('wcj_is_module_allowed_by_allowlist')||wcj_is_module_allowed_by_allowlist($id))&&(!wcj_is_module_enabled('modules_by_user_roles')||wcj_check_modules_by_user_roles($id));}
 public static function raw($key){global $wpdb;$r=$wpdb->get_row($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",$key),ARRAY_A);if($wpdb->last_error){throw new RuntimeException('Saved document configuration could not be read.');}return $r?(string)$r['option_value']:null;}
 /** No calls to native document-type getters: those can migrate legacy create_on values. */
 public static function project_types($raw){
  $types=array('invoice'=>'Invoice','proforma_invoice'=>'Proforma invoice','packing_slip'=>'Packing slip','credit_note'=>'Credit note');$warning='';$count=1;
  if(null!==$raw){if(!is_string($raw)||!preg_match('/\A-?(?:0|[1-9][0-9]{0,8})\z/D',$raw)){$count=0;$warning='The saved custom-document count needs full settings. Custom types are not guessed or changed here.';}else{$count=min((int)$raw,100);if($count<1||$count>100||$raw!==(string)$count){$warning='The saved custom-document count is outside the normal settings range. This view preserves it and shows only the bounded native slots.';}$count=max(0,$count);}}
  for($i=1;$i<=$count;$i++){$types[1===$i?'custom_doc':'custom_doc_'.$i]='Custom document #'.$i;}return array('types'=>$types,'warning'=>$warning,'custom_count'=>$count);
 }
 public static function types(){if(!self::allowed('pdf_invoicing')){return array('types'=>array(),'warning'=>'Ask an administrator for access to document type configuration.','custom_count'=>0);}return self::project_types(self::raw('wcj_invoicing_custom_doc_total_number'));}
 /** Bounded scalar/list decode; never call unserialize on arbitrary object graphs. */
 public static function list_value($raw){if(null===$raw||''===$raw){return array();}if(!is_string($raw)||strlen($raw)>16384){return null;}if('a:'!==substr($raw,0,2)){return null;}$a=@unserialize($raw,array('allowed_classes'=>false,'max_depth'=>2));if(!is_array($a)||count($a)>128||serialize($a)!==$raw){return null;}foreach($a as $k=>$v){if(!is_int($k)||!is_string($v)||strlen($v)>200||1!==preg_match('//u',$v)||null!==ReflectionReference::fromArrayElement($a,$k)){return null;}}return array_values($a);}
 public static function project_events($raw){
  if(null===$raw||''===$raw||'disabled'===$raw){return array('values'=>array(),'legacy'=>null!==$raw&&'disabled'===$raw,'supported'=>true);}
  $a=self::list_value($raw);if(null!==$a){return array('values'=>$a,'legacy'=>false,'supported'=>true);}
  if(is_string($raw)&&strlen($raw)<=200&&preg_match('/\A[a-zA-Z0-9_-]+\z/D',$raw)){return array('values'=>'wcj_pdf_invoicing_create_on_any_refund'===$raw?array('woocommerce_order_status_refunded','woocommerce_order_partially_refunded_notification'):array($raw),'legacy'=>true,'supported'=>true);}
  return array('values'=>array(),'legacy'=>false,'supported'=>false);
 }
 private static function text($v){return is_string($v)&&strlen($v)<=1000&&1===preg_match('//u',$v)?$v:'Unrecognized saved value';}
 private static function flag($v,$default){$v=null===$v?$default:$v;return 'yes'===$v?'On':('no'===$v?'Off':'Unrecognized saved value');}
 private static function selections($v,$empty){$a=self::list_value($v);if(null===$a){return 'Unrecognized saved selection; use full settings';}return $a?implode(', ',array_map(static function($x){return str_replace('_',' ',$x);},$a)):$empty;}
 public static function snapshot($type){
  $types=self::types();if(!isset($types['types'][$type])){throw new RuntimeException('Choose an available document type.');}$p='wcj_invoicing_'.$type.'_';$rows=array();
  if(self::allowed('pdf_invoicing')){$rows['Module switch']=self::flag(self::raw('wcj_pdf_invoicing_enabled'),'no');$e=self::project_events(self::raw($p.'create_on'));$labels=array();foreach($e['values'] as $v){$labels[]='manual'===$v||'wcj_pdf_invoicing_manual'===$v?'Manual':str_replace(array('woocommerce_order_status_','woocommerce_','wcj_pdf_invoicing_create_on_','_'),array('Order status: ','','', ' '),$v);}$rows['Creation rule']=!$e['supported']?'Unrecognized saved rule; use full settings':($labels?implode(', ',$labels):'No creation rule selected');if($e['legacy']){$rows['Legacy creation rule']='Shown without converting its saved storage.';}$rows['Edition generation scope']='free'===self::edition()&&'invoice'!==$type?'Free does not enable generation of this document type. Its visible appearance settings are separate.':'Included in this edition; saved rules and module switch still apply.';}
  if(self::allowed('pdf_invoicing_emails')){$rows['Selected email events']=self::selections(self::raw($p.'attach_to_emails'),'None selected');$rows['Attachment payment methods']=self::selections(self::raw($p.'payment_gateways'),'All methods (empty selection)');}
  if(self::allowed('pdf_invoicing_advanced')){$v=self::flag(self::raw('wcj_general_advanced_disable_save_sys_temp_dir'),'no');$rows['Temporary-file saving']='Off'===$v?'Allowed by saved settings':('On'===$v?'Disabled; attachment and ZIP output are affected':'Unrecognized saved setting');}
  if(self::allowed('pdf_invoicing_numbering')){$rows['Sequential mode']=self::flag(self::raw($p.'sequential_enabled'),'no');$v=self::raw($p.'numbering_counter');$rows['Saved sequence counter']=null===$v?'Not saved (native default 1)':self::text($v);$rows['Counter meaning']='Not a reserved or guaranteed next number. Formatting can change displayed existing numbers.';}
  if(self::allowed('pdf_invoicing_templates')){$v=self::raw($p.'template');$rows['Template']=null===$v?'No saved override; the supplied default applies':self::template_state($type,$v);}
  if(self::allowed('pdf_invoicing_display')){$rows['My Account document link switch']=self::flag(self::raw($p.'enabled_for_customers'),'no');$v=self::raw($p.'roles');$roles=self::list_value($v);$rows['Admin role configuration']=null===$v?'Default: administrator, shop manager':(null===$roles?'Unrecognized saved roles; use full settings':($roles?implode(', ',$roles):'Empty selection; native fallback is administrator'));$rows['Access distinction']='Link visibility is separate from authorization. Native access also recognizes the signed-in order owner.';}
  return array('type'=>$type,'label'=>$types['types'][$type],'warning'=>$types['warning'],'rows'=>$rows);
 }
 private static function template_state($type,$raw){
  if(!is_string($raw)||strlen($raw)>1000000||1!==preg_match('//u',$raw)){return 'Saved template not classified; preserved in full settings';}
  $name=0===strpos($type,'custom_doc')?'custom_doc':$type;$path=dirname(__DIR__).'/settings/pdf-invoicing/wcj-content-template-'.$name.'.html';$default=is_readable($path)?file_get_contents($path):false;
  if(false===$default||false!==strpos($default,'<?')){return 'Saved template; default comparison unavailable';}
  if('custom_doc'===$name){$nr='custom_doc'===$type?'1':substr($type,11);$default=str_replace(array('[wcj_custom_doc_number]','[wcj_custom_doc_date]'),array('[wcj_custom_doc_number doc_nr="'.$nr.'"]','[wcj_custom_doc_date doc_nr="'.$nr.'"]'),$default);}
  return $raw===$default?'Saved template matches the supplied default':'Saved custom or managed template; preserved unchanged';
 }
 public static function url(){return admin_url('admin.php?page=wcj-documents');}
 public static function native_url($id,$type='',$group=''){
  $tabs=array('generation-and-document-count'=>'pdf_invoicing_document_options_tab','existing-preview-and-tools'=>'pdf_invoicing_tools_options_tab','advanced-visibility-storage-and-rendering'=>'pdf_invoicing_advanced_advanced_options_tab','order-item-and-language-compatibility'=>'pdf_invoicing_advanced_item_name_tab','font-installation-and-download-policy'=>'pdf_invoicing_advanced_fonts_tab','order-metabox-controls'=>'pdf_invoicing_advanced_general_tab','report-output-format'=>'pdf_invoicing_advanced_report_tab');
  $tab=$tabs[$group]??'';
  if(in_array($id,array('pdf_invoicing_display','pdf_invoicing_emails','pdf_invoicing_footer','pdf_invoicing_header','pdf_invoicing_numbering','pdf_invoicing_page','pdf_invoicing_styling','pdf_invoicing_templates'),true)&&$type&&isset(self::types()['types'][$type])){$tab=$id.'_'.$type.'_tab';}
  if('pdf_invoicing_paid_stamp'===$id){$tab='pdf_invoicing_paid_stamp_invoice_tab';}
  return admin_url(wcj_admin_tab_url().'&wcj-cat=pdf_invoicing&section='.$id.($tab?'&active_tab='.$tab:''));
 }
 public static function link($url,$label){return '<a target="_blank" rel="noopener noreferrer" href="'.esc_url($url).'">'.esc_html($label.' (new tab)').'</a>';}
 public static function entry(){foreach(self::groups() as $g){if(self::allowed($g['module'])){echo '<p><a href="'.esc_url(self::url()).'">Order documents: appearance, numbering and delivery</a></p>';return;}}}
 public static function help($module='',$section='',$type='',$selected=array()){
  $ed=self::edition();foreach(self::groups() as $g){if(($selected&&!in_array($g['id'],$selected,true))||($module&&$module!==$g['module'])||($section&&$section!==$g['section'])||empty($g['members'][$ed])||!self::allowed($g['module'])){continue;}
   echo '<article class="wcj-document-group" data-document-group="'.esc_attr($g['id']).'"><h3>'.esc_html($g['label']).'</h3><p>'.esc_html($g['context']).'</p><p>'.self::link(self::native_url($g['module'],$type,$g['id']),'Full settings').' | '.self::link($g['guide'],'Guide: '.$g['label']).'</p><details><summary>Settings covered</summary><ul>';foreach(array_unique($g['members'][$ed]) as $m){echo '<li>'.esc_html($m).'</li>';}echo '</ul></details></article>';
  }
 }
 public static function screen_help(){
  if(!current_user_can('manage_woocommerce')){return;}$page=isset($_GET['page'])&&is_string($_GET['page'])?$_GET['page']:'';$module=isset($_GET['section'])&&is_string($_GET['section'])?$_GET['section']:'';$selected=array();
  if('wcj-plugins'===$page&&in_array($module,array_unique(array_column(self::groups(),'module')),true)&&self::allowed($module)){}
  elseif('wcj-tools'===$page&&isset($_GET['tab'])&&is_string($_GET['tab'])&&in_array($_GET['tab'],array('invoices_report','renumerate_invoices'),true)&&self::allowed('pdf_invoicing')){$module='';$selected=array('existing-preview-and-tools');}
  else{$screen=get_current_screen();if(!$screen||!in_array($screen->id,array('shop_order','edit-shop_order','woocommerce_page_wc-orders'),true)||!self::allowed('pdf_invoicing_display')){return;}$module='';$selected=array('order-metabox-controls','admin-order-list-actions-and-labels','number-format-and-sequence');}
  echo '<div class="notice notice-info wcj-document-context"><p><a href="'.esc_url(self::url()).'">Order documents workspace</a>. Help opens separately and leaves this screen in place.</p><details><summary>Document settings and actions: effects and guidance</summary>';self::help($module,'','',$selected);echo '</details></div>';
 }

 public static function register(){if(current_user_can('manage_woocommerce')){add_submenu_page('woocommerce','Order documents','Order documents','manage_woocommerce','wcj-documents',array(__CLASS__,'render'));}}
 public static function render(){
  if(!current_user_can('manage_woocommerce')){wp_die('Ask an administrator for access.');}wp_enqueue_style('wcj-document-workspace',wcj_plugin_url().'/assets/css/admin/wcj-document-workspace.css',array(),'1.0');
  echo '<div class="wrap wcj-document-workspace"><h1>Order documents</h1><p>Choose a document, understand its saved configuration, then change only what you need. Viewing this workspace does not save its settings, generate documents, reserve numbers or send emails. Some older saved settings may be updated automatically when your site loads.</p>';
  try{$types=self::types();$type=isset($_GET['type'])&&is_string($_GET['type'])?$_GET['type']:'invoice';if(!isset($types['types'][$type])){if(!$types['types']){echo '<p>'.esc_html($types['warning']).'</p>';foreach(array('Appearance','Numbering and records','Delivery and access','Advanced and tools') as $lane){echo '<h2>'.esc_html($lane).'</h2>';self::help('',$lane);}echo '</div>';return;}throw new RuntimeException('This document type is unavailable. Choose the workspace link to return.');}$snap=self::snapshot($type);
   echo '<form method="get" class="wcj-document-picker"><input type="hidden" name="page" value="wcj-documents"><label for="wcj-document-type">Document type</label> <select id="wcj-document-type" name="type">';foreach($types['types'] as $id=>$label){echo '<option value="'.esc_attr($id).'"'.selected($type,$id,false).'>'.esc_html($label).'</option>';}echo '</select> <button class="button" type="submit">Show document</button></form>';
   if($snap['warning']){echo '<p role="status">'.esc_html($snap['warning']).'</p>';}echo '<section class="wcj-document-current"><h2>Current configuration: '.esc_html($snap['label']).'</h2><p>Saved choices only, not a document or delivery history.</p><dl>';$extra=array();foreach($snap['rows'] as $label=>$value){if(in_array($label,array('Legacy creation rule','Attachment payment methods','Temporary-file saving','Sequential mode','Saved sequence counter','Counter meaning','Template','Admin role configuration','Access distinction'),true)){$extra[$label]=$value;continue;}echo '<div><dt>'.esc_html($label).'</dt><dd>'.esc_html($value).'</dd></div>';}echo '</dl>';if($extra){echo '<details><summary>Numbering, template, attachment conditions and access details</summary><dl>';foreach($extra as $label=>$value){echo '<div><dt>'.esc_html($label).'</dt><dd>'.esc_html($value).'</dd></div>';}echo '</dl></details>';}echo '</section>';
   if('invoice'===$type&&WCJ_Task_Finder::allowed('pdf_invoicing')){echo '<p>'.self::link(WCJ_Invoice_Job::url(),'Brand your invoice: existing task and fictional sample').'</p>';}
   echo '<nav aria-label="Document settings sections">';foreach(array('Appearance','Numbering and records','Delivery and access','Advanced and tools') as $i=>$lane){echo '<a href="#wcj-doc-section-'.$i.'">'.esc_html($lane).'</a> ';}echo '</nav>';
   foreach(array('Appearance','Numbering and records','Delivery and access','Advanced and tools') as $i=>$lane){echo '<details class="wcj-document-section" id="wcj-doc-section-'.$i.'"'.('Delivery and access'===$lane?' open':'').'><summary><h2>'.esc_html($lane).'</h2></summary>';if('Delivery and access'===$lane&&self::allowed('pdf_invoicing_display')){self::forms($type);}self::help('',$lane,$type);echo '</details>';}
   echo '<p>Switches, resets, numbering, templates and record operations remain in full settings. Restore previous below changes only the matching wording field, not documents, numbers or mail.</p>';
  }catch(Throwable $e){echo '<p role="alert">'.esc_html($e->getMessage()).'</p><p><a href="'.esc_url(self::url()).'">Return to document selection</a></p>';}echo '</div>';
 }
 private static function forms($type){
  wp_enqueue_script('wcj-document-workspace',wcj_plugin_url().'/assets/js/admin/wcj-document-workspace.js',array(),'1.0',true);$nonces=array();foreach(WCJ_Document_Label_Job::OPS as $op){$nonces[$op]=wp_create_nonce('wcj_document_label_'.$op);}wp_localize_script('wcj-document-workspace','wcjDocumentWorkspace',array('url'=>admin_url('admin-ajax.php'),'nonces'=>$nonces,'type'=>$type));
  foreach(array('admin_title'=>'Admin document label','link_text'=>'My Account document link text') as $field=>$label){echo '<form class="wcj-document-label" data-field="'.esc_attr($field).'"><h3>'.esc_html($label).'</h3><p>'.esc_html('admin_title'===$field?'Changes the document name used in admin screens and the title in individual PDF file properties. It does not edit heading or template settings or separate column and Thank You settings; their default wording may use this name. Saving does not alter copies already emailed or downloaded. When Booster generates an individual PDF again, including through its normal My Account link, the title in the PDF file properties uses the current admin label.':'Changes the My Account document link text only. It does not turn the customer link or document creation on.').'</p><label for="wcj-doc-'.$field.'">'.esc_html($label).'</label><input id="wcj-doc-'.$field.'" name="value" type="text" maxlength="120" disabled aria-describedby="wcj-doc-hint-'.$field.'"><p id="wcj-doc-hint-'.$field.'">Use short plain text. Leaving this blank saves an empty value; what appears depends on the document setting.</p><details><summary>Wording limits and recovery</summary><p>Up to 120 UTF-8 bytes; some letters use more than one byte. Use full settings for markup, shortcodes or the single digit 0. Restore previous is available for seven days for your latest save of this field in this workspace, when the current setting matches that save and recovery information is still available. It restores the earlier value, including an empty value or no saved setting. It does not change document records, numbers or sent emails.</p></details><p>Wording example only, not PDF or customer output: <span class="wcj-document-example"></span></p><p class="wcj-document-saved"></p><p class="wcj-document-status" role="status" aria-live="polite">Loading current wording...</p><button class="button button-primary" type="submit" disabled>Save this wording</button> <button class="button wcj-document-restore" type="button" disabled>Restore previous</button> <button class="button wcj-document-reload" type="button">Discard draft and reload</button><p>'.self::link(self::native_url('pdf_invoicing_display',$type),'Full Display settings').'</p></form>';}
 }
}
add_action('admin_menu',array('WCJ_Document_Workspace','register'),99);
add_action('admin_notices',array('WCJ_Document_Workspace','screen_help'),40);
